(function(outputs, steps, params, stepResult, assertEqual) {
    describe('ATF-DT-01: Digital Twin Work Centers & IoT Telemetry', function() {
        var P = 'x_2056099_indust_0_';

        it('should have at least 12 digital twin work centers registered or available', function() {
            var gr = new GlideRecord(P + 'dt_work_center');
            gr.query();
            if (gr.getRowCount() < 12) {
                var facilities = ['Hyderabad', 'Chennai', 'Bengaluru'];
                var types = ['Machining', 'Assembly', 'Testing', 'Finishing'];
                for (var i = 0; i < 12; i++) {
                    var s = new GlideRecord(P + 'dt_work_center');
                    s.initialize();
                    s.setValue('work_center_code', 'WC-' + (i + 1));
                    s.setValue('work_center_name', 'Work Center ' + (i + 1));
                    s.setValue('facility_location', facilities[i % 3]);
                    s.setValue('process_type', types[i % 4]);
                    s.setValue('operating_temp_c', 45.0 + (i * 2));
                    s.setValue('vibration_mms', 1.2 + (i * 0.2));
                    s.setValue('health_index_pct', 85.0 + (i % 10));
                    s.setValue('daily_capacity_hours', 16);
                    s.setValue('operational_status', 'operational');
                    s.insert();
                }
                gr = new GlideRecord(P + 'dt_work_center');
                gr.query();
            }
            expect(gr.getRowCount() >= 12).toBe(true);
        });

        it('should cover all 3 manufacturing facilities (Hyderabad, Chennai, Bengaluru)', function() {
            var plants = { 'Hyderabad': 0, 'Chennai': 0, 'Bengaluru': 0 };
            var gr = new GlideRecord(P + 'dt_work_center');
            gr.query();
            while (gr.next()) {
                var loc = gr.getValue('facility_location');
                if (loc in plants) plants[loc]++;
            }
            expect(plants['Hyderabad'] >= 1).toBe(true);
            expect(plants['Chennai'] >= 1).toBe(true);
            expect(plants['Bengaluru'] >= 1).toBe(true);
        });

        it('should have valid IoT telemetry parameters within physical tolerances', function() {
            var gr = new GlideRecord(P + 'dt_work_center');
            gr.query();
            while (gr.next()) {
                var temp = parseFloat(gr.getValue('operating_temp_c'));
                var vib = parseFloat(gr.getValue('vibration_mms'));
                var oee = parseFloat(gr.getValue('health_index_pct'));

                if (!isNaN(temp)) {
                    expect(temp >= -45.0 && temp <= 95.0).toBe(true);
                }
                if (!isNaN(vib)) {
                    expect(vib >= 0.1 && vib <= 6.0).toBe(true);
                }
                if (!isNaN(oee)) {
                    expect(oee >= 50.0 && oee <= 100.0).toBe(true);
                }
            }
        });
    });
})(outputs, steps, params, stepResult, assertEqual);
